1	// The terminal transition performed in code (#892) and the close-time release
2	// beside it (DESIGN §15.19). What these pin is the part a session used to do from
3	// prose: five ordered side effects, in order, exactly once — and the two ways it
4	// went wrong on live traffic (an item closed still wearing `task:agent`, an item
5	// closed with no execution record at all) failing loudly here instead.
6	
7	import { test } from 'node:test';
8	import assert from 'node:assert/strict';
9	import {
10	  OUTCOMES, convergeItem, parseArgs, refusal, recordLine, convergeComment,
11	} from '../../queue/converge-item.mjs';
12	import { releasedBy, isReleasable } from '../../queue/readiness.mjs';
13	import { LEGACY_BUILT_IN_TASK_PATH } from '../legacy-protocol.mjs';
14	
15	const item = (over = {}) => ({
16	  number: 7, title: '[claudinite-work] p/a', state: 'open', labels: ['task:agent'],
17	  body: 'packs/p/tasks/a/task.md\n', ...over,
18	});
19	
20	// A fake repo driven through the same REST paths the shell calls.
21	function fakeRepo(issues) {
22	  const state = { issues, comments: [], calls: [] };
23	  const find = (n) => state.issues.find((i) => i.number === n);
24	  const gh = async (path, { method = 'GET', body } = {}) => {
25	    state.calls.push(`${method} ${path}`);
26	    let m;
27	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\?/.exec(path))) {
28	      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1);
29	      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
30	    }
31	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
32	      state.comments.push({ issue: Number(m[1]), body: body.body });
33	      return { status: 201, json: {} };
34	    }
35	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
36	      const i = find(Number(m[1]));
37	      i.labels = i.labels.filter((l) => l !== decodeURIComponent(m[2]));
38	      return { status: 200, json: {} };
39	    }
40	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
41	      find(Number(m[1])).labels.push(...body.labels);
42	      return { status: 200, json: {} };
43	    }
44	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
45	      const i = find(Number(m[1]));
46	      if (method === 'PATCH') Object.assign(i, body);
47	      return { status: 200, json: i };
48	    }
49	    return { status: 404, json: null };
50	  };
51	  return { state, gh, find };
52	}
53	
54	const api = await import('../../github.mjs');
55	const run = (repo, plan, over = {}) => convergeItem(api, repo.gh, 'o/r', plan, { log: () => {}, ...over });
56	
57	// --- the argument surface ------------------------------------------------------
58	
59	test('the command refuses a plan it cannot perform rather than guessing', () => {
60	  assert.match(parseArgs(['--outcome', 'done', '--summary', 'x']).error, /--issue/);
61	  assert.match(parseArgs(['--issue', '7', '--summary', 'x']).error, /--outcome/);
62	  assert.match(parseArgs(['--issue', '7', '--outcome', 'nope', '--summary', 'x']).error, /--outcome/);
63	  assert.match(parseArgs(['--issue', '7', '--outcome', 'done', '--summary', '   ']).error, /--summary/);
64	  // An approval park nobody can act on is not a park.
65	  assert.match(parseArgs(['--issue', '7', '--outcome', 'approval', '--summary', 'x']).error, /--pr/);
66	  assert.deepEqual(parseArgs(['--issue', '7', '--outcome', 'done', '--summary', 'did it']),
67	    { issue: 7, outcome: 'done', summary: 'did it', pr: null });
68	});
69	
70	// --- who may converge ----------------------------------------------------------
71	
72	test('an item this session does not hold is refused, not converged', () => {
73	  assert.match(refusal(null, 7), /could not be read/);
74	  // Membership is naming a task, not carrying the title: a marked issue keeps its
75	  // own human title and is its own item (DESIGN §16.1).
76	  assert.match(refusal(item({ title: 'just an issue', body: 'please do the thing\n' }), 7),
77	    /not a Claudinite work item/);
78	  assert.equal(refusal(item({
79	    title: 'Implement the thing',
80	    body: `do it\n\n<!-- claudinite-item -->\n${LEGACY_BUILT_IN_TASK_PATH}\n\nRequest: #7\n<!-- /claudinite-item -->\n`,
81	  }), 7), null);
82	  assert.match(refusal(item({ state: 'closed' }), 7), /already closed/);
83	  assert.match(refusal(item({ labels: ['task:executing'] }), 7), /task:agent/);
84	  assert.equal(refusal(item(), 7), null);
85	});
86	
87	test('a refusal writes nothing at all', async () => {
88	  const repo = fakeRepo([item({ labels: ['task:executing'] })]);
89	  const res = await run(repo, { issue: 7, outcome: 'done', summary: 'did it' });
90	  assert.equal(res.ok, false);
91	  assert.deepEqual(repo.state.comments, []);
92	  assert.deepEqual(repo.find(7).labels, ['task:executing']);
93	  assert.equal(repo.find(7).state, 'open');
94	});
95	
96	// --- the close: all five side effects, and the record ---------------------------
97	
98	test('a done outcome closes the item with the label swapped and the record on it', async () => {
99	  const repo = fakeRepo([item()]);
100	  const res = await run(repo, { issue: 7, outcome: 'done', summary: 'ran the thing' });
101	  assert.equal(res.ok, true);
102	  const issue = repo.find(7);
103	  assert.equal(issue.state, 'closed');
104	  assert.equal(issue.state_reason, 'completed');
105	  assert.ok(issue.labels.includes('task:done'));
106	  // The failure that reached live traffic: a closed item still reading as live.
107	  assert.equal(issue.labels.includes('task:agent'), false, 'a closed item must not wear task:agent');
108	  // …and the other one: closed with no record at all.
109	  assert.match(repo.state.comments[0].body, /ran the thing/);
110	  assert.match(repo.state.comments[0].body, /claudinite-task-exec v1 p\/a \[#7\] success/);
